import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import {
  Copy, Mail, Globe, Link2, Info, Inbox, Send, Key,
  CheckCircle2, AlertCircle, Save, FileText, Search,
  Zap, Bell, Shield, Eye, EyeOff, ExternalLink,
  ArrowRight, Plug, Settings2, TestTube, Loader2,
  AlertTriangle, XCircle, RefreshCw
} from "lucide-react";
import { Table, TableHeader, TableBody, TableHead, TableRow, TableCell } from "@/components/ui/table";
import EmailIngestLogsCard from "./EmailIngestLogsCard";

const WEBHOOK_URL = "https://zkzontawprihrzpayeam.supabase.co/functions/v1/email-ingest";

async function adminCall(body: any) {
  const { data: { session } } = await supabase.auth.getSession();
  const res = await supabase.functions.invoke("admin-users", {
    headers: { Authorization: `Bearer ${session?.access_token}` },
    body,
  });
  if (res.error) throw new Error(res.error.message || "Admin call failed");
  const data = res.data as any;
  if (data?.error) throw new Error(data.error);
  return data;
}

// ─── Resend health state ───
interface ResendHealth {
  keyValid: boolean;
  domainVerified: boolean;
  domainName: string;
  fromEmail: string;
  totalDomains: number;
}

// ─── Step indicator for setup wizard ───
function SetupStep({ step, title, done, active }: { step: number; title: string; done: boolean; active: boolean }) {
  return (
    <div className="flex items-center gap-3">
      <div className={`h-8 w-8 rounded-full flex items-center justify-center text-sm font-bold shrink-0 transition-colors ${
        done ? "bg-green-500 text-white" : active ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
      }`}>
        {done ? <CheckCircle2 className="h-4 w-4" /> : step}
      </div>
      <span className={`text-sm font-medium ${done ? "text-green-600 dark:text-green-400" : active ? "text-foreground" : "text-muted-foreground"}`}>
        {title}
      </span>
    </div>
  );
}

// ─── Toggle row component ───
function ToggleRow({
  icon: Icon, label, description, checked, onToggle, disabled = false
}: {
  icon: React.ElementType; label: string; description: string;
  checked: boolean; onToggle: (v: boolean) => void; disabled?: boolean;
}) {
  return (
    <div className="flex items-center justify-between rounded-xl border border-border p-4 hover:bg-muted/30 transition-colors">
      <div className="flex items-center gap-3">
        <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
          <Icon className="h-4 w-4 text-primary" />
        </div>
        <div className="space-y-0.5">
          <Label className="text-sm font-medium cursor-pointer">{label}</Label>
          <p className="text-xs text-muted-foreground">{description}</p>
        </div>
      </div>
      <Switch checked={checked} onCheckedChange={onToggle} disabled={disabled} />
    </div>
  );
}

// ─── Health Alert Banner ───
function HealthBanner({ health, loading, onVerify }: {
  health: ResendHealth | null;
  loading: boolean;
  onVerify: () => void;
}) {
  if (loading) {
    return (
      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
      </div>
    );
  }

  if (!health) return null;

  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];

  if (!health.keyValid) {
    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
  }
  if (health.keyValid && !health.domainVerified) {
    issues.push({
      icon: AlertTriangle,
      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
      severity: "warning",
    });
  }

  if (issues.length === 0 && health.keyValid) {
    return (
      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-green-600" />
            <span className="text-sm font-medium text-green-700 dark:text-green-400">
              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
            </span>
          </div>
          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
            <RefreshCw className="h-3 w-3" /> Recheck
          </Button>
        </div>
        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {issues.map((issue, i) => (
        <div
          key={i}
          className={`rounded-lg border p-3 flex items-start gap-2 ${
            issue.severity === "error"
              ? "border-destructive/50 bg-destructive/10 text-destructive"
              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
          }`}
        >
          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
          <p className="text-xs">{issue.text}</p>
        </div>
      ))}
      <div className="flex justify-end">
        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
          <RefreshCw className="h-3 w-3" /> Recheck
        </Button>
      </div>
    </div>
  );
}

const EmailSettingsTab = () => {
  const qc = useQueryClient();
  const [search, setSearch] = useState("");
  const [testEmailTo, setTestEmailTo] = useState("");
  const [sendingTest, setSendingTest] = useState(false);
  const [showKey, setShowKey] = useState(false);
  const [regeneratingUser, setRegeneratingUser] = useState<string | null>(null);
  const [dnsChecking, setDnsChecking] = useState(false);
  const [dnsResult, setDnsResult] = useState<{
    status: string;
    mx_records: { exchange: string; priority: number }[];
    points_to_expected: boolean;
  } | null>(null);

  const [resendApiKey, setResendApiKey] = useState("");
  const [fromAddress, setFromAddress] = useState("");
  const [fromName, setFromName] = useState("");
  const [inboundDomain, setInboundDomain] = useState("");
  const [inboundWebhookSecret, setInboundWebhookSecret] = useState("");
  const [showWebhookSecret, setShowWebhookSecret] = useState(false);
  const [configLoaded, setConfigLoaded] = useState(false);

  // Resend health state
  const [resendHealth, setResendHealth] = useState<ResendHealth | null>(null);
  const [healthLoading, setHealthLoading] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["admin_config"],
    queryFn: () => adminCall({ action: "get_config" }),
  });

  useEffect(() => {
    if (config && !configLoaded) {
      setResendApiKey(config.resend_api_key_masked || "");
      setFromAddress(config.email_from_address || "noreply@rankora.co");
      setFromName(config.email_from_name || "Rankora");
      setInboundDomain(config.inbound_email_domain || "inbound.rankora.co");
      setInboundWebhookSecret(config.resend_inbound_webhook_secret_masked || "");
      setConfigLoaded(true);
    }
  }, [config, configLoaded]);

  // Auto-check health when config loads and key exists
  useEffect(() => {
    if (config?.has_resend_key && !resendHealth && !healthLoading) {
      verifyResendConnection();
    }
  }, [config?.has_resend_key]);

  const { data: templates = [] } = useQuery({
    queryKey: ["email_templates"],
    queryFn: () => adminCall({ action: "get_templates" }),
  });

  const { data: users = [] } = useQuery({
    queryKey: ["admin_users_email"],
    queryFn: async () => {
      const { data: { session } } = await supabase.auth.getSession();
      const res = await supabase.functions.invoke("admin-users", {
        headers: { Authorization: `Bearer ${session?.access_token}` },
      });
      if (res.error) throw res.error;
      return res.data as Array<{
        id: string; email: string; inbox_email: string | null;
        email_enabled: boolean; credits: number; plan: string;
      }>;
    },
  });

  // ─── Verify Resend Connection ───
  const verifyResendConnection = async () => {
    setHealthLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: "RESEND_API_KEY" },
      });
      if (error) throw error;

      const d = data.details || {};
      setResendHealth({
        keyValid: d.keyValid ?? false,
        domainVerified: d.domainVerified ?? false,
        domainName: d.domainName || "",
        fromEmail: d.fromEmail || "",
        totalDomains: d.totalDomains || 0,
      });

      // Also refresh the integrations query
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (e: any) {
      toast.error("Failed to verify connection: " + e.message);
      setResendHealth({
        keyValid: false,
        domainVerified: false,
        domainName: "",
        fromEmail: "",
        totalDomains: 0,
      });
    } finally {
      setHealthLoading(false);
    }
  };

  // ─── Mutations ───
  const updateConfig = useMutation({
    mutationFn: (updates: Record<string, any>) => adminCall({ action: "update_config", updates }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin_config"] }),
    onError: (e: any) => toast.error(e.message),
  });

  const toggleOutbound = useMutation({
    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { outbound_email_enabled: enabled } }),
    onSuccess: () => { toast.success("Outbound email updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const toggleGlobal = useMutation({
    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { email_ingestion_enabled: enabled } }),
    onSuccess: () => { toast.success("Email ingestion updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const toggleNotification = useMutation({
    mutationFn: ({ field, enabled }: { field: string; enabled: boolean }) =>
      adminCall({ action: "update_config", updates: { [field]: enabled } }),
    onSuccess: () => { toast.success("Notification updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const saveResendConfig = useMutation({
    mutationFn: async () => {
      const updates: Record<string, any> = {
        email_from_address: fromAddress,
        email_from_name: fromName,
      };
      if (resendApiKey && !resendApiKey.includes("***")) {
        updates.resend_api_key = resendApiKey;
      }
      return adminCall({ action: "update_config", updates });
    },

  onSuccess: () => {
    toast.success("Resend settings saved!");
    qc.invalidateQueries({ queryKey: ["admin_config"] });
    // Re-verify connection after saving
    setTimeout(() => verifyResendConnection(), 500);
  },
  onError: (e: any) => toast.error(e.message),
});

const updateTemplate = useMutation({
  mutationFn: ({ id, subject, body_html }: { id: string; subject: string; body_html: string }) =>
    adminCall({ action: "update_template", template_id: id, subject, body_html }),
  onSuccess: () => { toast.success("Template saved"); qc.invalidateQueries({ queryKey: ["email_templates"] }); },
  onError: (e: any) => toast.error(e.message),
});

const toggleUser = useMutation({
  mutationFn: async ({ userId, enabled }: { userId: string; enabled: boolean }) => {
    const { data: { session } } = await supabase.auth.getSession();
    const res = await supabase.functions.invoke("admin-users", {
      method: "POST",
      headers: { Authorization: `Bearer ${session?.access_token}` },
      body: { user_id: userId, email_enabled: enabled },
    });
    if (res.error) throw res.error;
  },
  onSuccess: () => { toast.success("User email updated"); qc.invalidateQueries({ queryKey: ["admin_users_email"] }); },
  onError: (e: any) => toast.error(e.message),
});

const handleSendTestEmail = async () => {
  if (!testEmailTo) { toast.error("Enter a recipient email"); return; }
  setSendingTest(true);
  try {
    const res = await supabase.functions.invoke("send-email", {
      body: {
        to: testEmailTo,
        template_key: "ranking_complete",
        variables: { user_name: "Admin", job_title: "Test Job", resume_count: "5", job_id: "test", app_url: window.location.origin },
      },
    });
    if (res.error) throw new Error(res.error.message);
    const data = res.data as any;
    if (data?.error) {
      toast.error(data.error);
    } else if (data?.skipped) {
      toast.error("Email skipped — check outbound is enabled");
    } else {
      toast.success(`Test email sent to ${testEmailTo}`);
    }
  } catch (e: any) { toast.error(e.message); }
  finally { setSendingTest(false); }
};

const copyToClipboard = (text: string) => { navigator.clipboard.writeText(text); toast.success("Copied!"); };

const filtered = users.filter(
  (u) => u.email?.toLowerCase().includes(search.toLowerCase()) || u.inbox_email?.toLowerCase().includes(search.toLowerCase())
);

const globalEnabled = config?.email_ingestion_enabled ?? true;
const outboundEnabled = config?.outbound_email_enabled ?? false;
const notifyRankingComplete = config?.email_notify_ranking_complete ?? true;
const notifyResumeReceived = config?.email_notify_resume_received ?? true;
const hasApiKey = !!config?.has_resend_key;
const maskedKey = hasApiKey && !resendApiKey ? "***hidden***" : resendApiKey;

// Wizard step states
const step1Done = hasApiKey;
const step2Done = hasApiKey && !!fromAddress;
const step3Done = step2Done && outboundEnabled;

return (
  <div className="space-y-6">
    <div className="flex items-center justify-between">
      <div>
        <h2 className="text-xl font-semibold">Email Settings</h2>
        <p className="text-sm text-muted-foreground">Manage email sending, receiving, and templates</p>
      </div>
      <Badge variant={hasApiKey && outboundEnabled ? "default" : "secondary"} className={`gap-1.5 px-3 py-1 ${hasApiKey && outboundEnabled ? "bg-green-600 hover:bg-green-700" : ""}`}>
        {hasApiKey && outboundEnabled ? <><CheckCircle2 className="h-3 w-3" /> Connected</> : <><AlertCircle className="h-3 w-3" /> Not Connected</>}
      </Badge>
    </div>

    <Tabs defaultValue="connect" className="w-full">
      <TabsList className="grid w-full grid-cols-4 h-11">
        <TabsTrigger value="connect" className="gap-1.5"><Plug className="h-3.5 w-3.5" /> Connect</TabsTrigger>
        <TabsTrigger value="notifications" className="gap-1.5"><Bell className="h-3.5 w-3.5" /> Notifications</TabsTrigger>
        <TabsTrigger value="templates" className="gap-1.5"><FileText className="h-3.5 w-3.5" /> Templates</TabsTrigger>
        <TabsTrigger value="inbound" className="gap-1.5"><Inbox className="h-3.5 w-3.5" /> Inbound</TabsTrigger>
      </TabsList>

      {/* ─── Connect Tab ─── */}
      <TabsContent value="connect" className="space-y-5 mt-5">
        {/* Health Banner — shows at top when key exists */}
        {hasApiKey && (
          <HealthBanner health={resendHealth} loading={healthLoading} onVerify={verifyResendConnection} />
        )}

        {/* Setup Wizard */}
        <Card>
          <CardHeader className="pb-4">
            <CardTitle className="text-base flex items-center gap-2">
              <Zap className="h-4 w-4 text-amber-500" /> Quick Setup
            </CardTitle>
            <CardDescription>Follow these 3 steps to start sending emails</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-2 mb-5">
              <SetupStep step={1} title="Add API Key" done={step1Done} active={!step1Done} />
              <ArrowRight className="h-4 w-4 text-muted-foreground shrink-0" />
              <SetupStep step={2} title="Set Sender" done={step2Done} active={step1Done && !step2Done} />
              <ArrowRight className="h-4 w-4 text-muted-foreground shrink-0" />
              <SetupStep step={3} title="Enable & Test" done={step3Done} active={step2Done && !step3Done} />
            </div>

            {!step1Done && (
              <div className="rounded-lg border border-dashed border-primary/40 bg-primary/5 p-4 space-y-2">
                <p className="text-sm font-medium text-foreground">Let's get started!</p>
                <p className="text-xs text-muted-foreground">
                  You need a Resend account to send emails. Sign up for free at resend.com.
                </p>
                <Button variant="outline" size="sm" className="gap-1.5" asChild>
                  <a href="https://resend.com/signup" target="_blank" rel="noopener noreferrer">
                    <ExternalLink className="h-3 w-3" /> Create Resend Account
                  </a>
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Resend Credentials Card */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Key className="h-4 w-4" /> Resend Credentials
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label className="text-sm font-medium">API Key</Label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Input
                    type={showKey ? "text" : "password"}
                    placeholder="re_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                    value={configLoaded ? maskedKey : ""}
                    onChange={(e) => setResendApiKey(e.target.value)}
                    className="font-mono text-sm pr-10"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="absolute right-1 top-1/2 -translate-y-1/2 h-7 w-7"
                    onClick={() => setShowKey(!showKey)}
                  >
                    {showKey ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                  </Button>
                </div>
              </div>
              <p className="text-xs text-muted-foreground">
                Find it at{" "}
                <a href="https://resend.com/api-keys" target="_blank" rel="noopener noreferrer" className="text-primary underline">
                  Resend Dashboard → API Keys
                </a>
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Label className="text-sm font-medium">From Email</Label>
                  {resendHealth && hasApiKey && (
                    resendHealth.domainVerified ? (
                      <Badge variant="default" className="gap-1 text-[10px] px-1.5 py-0 bg-green-600">
                        <CheckCircle2 className="h-2.5 w-2.5" /> Verified
                      </Badge>
                    ) : (
                      <Badge variant="destructive" className="gap-1 text-[10px] px-1.5 py-0">
                        <XCircle className="h-2.5 w-2.5" /> Not Verified
                      </Badge>
                    )
                  )}
                </div>
                <Input
                  type="email"
                  placeholder="noreply@yourdomain.com"
                  value={fromAddress}
                  onChange={(e) => setFromAddress(e.target.value)}
                />
                <p className="text-xs text-muted-foreground">Domain must be verified in Resend</p>
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium">From Name</Label>
                <Input
                  placeholder="Rankora"
                  value={fromName}
                  onChange={(e) => setFromName(e.target.value)}
                />
              </div>
            </div>

            <div className="flex gap-2">
              <Button onClick={() => saveResendConfig.mutate()} disabled={saveResendConfig.isPending} className="gap-2">
                <Save className="h-4 w-4" />
                {saveResendConfig.isPending ? "Saving..." : "Save Credentials"}
              </Button>
              {hasApiKey && (
                <Button
                  variant="outline"
                  onClick={verifyResendConnection}
                  disabled={healthLoading}
                  className="gap-2"
                >
                  {healthLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                  Verify Connection
                </Button>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Master Toggle + Test */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Settings2 className="h-4 w-4" /> Email Sending
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <ToggleRow
              icon={Send}
              label="Enable Outbound Emails"
              description="Turn on email sending to users via Resend"
              checked={outboundEnabled}
              onToggle={(v) => toggleOutbound.mutate(v)}
            />

            {/* Domain not verified warning */}
            {hasApiKey && outboundEnabled && resendHealth && !resendHealth.domainVerified && resendHealth.keyValid && (
              <div className="rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 p-3 flex items-start gap-2">
                <AlertTriangle className="h-4 w-4 text-amber-600 shrink-0 mt-0.5" />
                <div className="space-y-1">
                  <p className="text-xs font-medium text-amber-700 dark:text-amber-400">
                    Domain Not Verified
                  </p>
                  <p className="text-xs text-amber-600 dark:text-amber-500">
                    The domain for <strong>{fromAddress}</strong> is not verified in Resend. Emails will fail until the domain is added and DNS records are configured.{" "}
                    <a href="https://resend.com/domains" target="_blank" rel="noopener noreferrer" className="underline font-medium">
                      Verify in Resend
                    </a>
                  </p>
                </div>
              </div>
            )}

            {/* Test Email — only show when connected */}
            {hasApiKey && outboundEnabled && (
              <div className="rounded-xl border border-dashed border-green-300 dark:border-green-800 bg-green-50/50 dark:bg-green-950/30 p-4 space-y-3">
                <div className="flex items-center gap-2">
                  <TestTube className="h-4 w-4 text-green-600" />
                  <span className="text-sm font-medium text-green-700 dark:text-green-400">Send a Test Email</span>
                </div>
                <div className="flex gap-2">
                  <Input
                    type="email"
                    placeholder="your@email.com"
                    value={testEmailTo}
                    onChange={(e) => setTestEmailTo(e.target.value)}
                    className="flex-1"
                  />
                  <Button onClick={handleSendTestEmail} disabled={sendingTest} variant="outline" className="gap-1.5 shrink-0 border-green-300 dark:border-green-800 hover:bg-green-100 dark:hover:bg-green-900">
                    <Send className="h-3.5 w-3.5" />
                    {sendingTest ? "Sending..." : "Send Test"}
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </TabsContent>

      {/* ─── Notifications Tab ─── */}
      <TabsContent value="notifications" className="space-y-5 mt-5">
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Bell className="h-4 w-4" /> Email Notifications
            </CardTitle>
            <CardDescription>Choose which events trigger email notifications to users</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {!outboundEnabled && (
              <div className="rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 p-3 flex items-center gap-2 mb-2">
                <AlertCircle className="h-4 w-4 text-amber-600 shrink-0" />
                <p className="text-xs text-amber-700 dark:text-amber-400">
                  Outbound email is disabled. Enable it in the <strong>Connect</strong> tab first.
                </p>

                                ) : (
                                  <RefreshCw className="h-3 w-3" />
                                )}
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>

          {/* Logs */}
          <EmailIngestLogsCard />
        </TabsContent>
      </Tabs>
    </div>
  );
};

