}

// ─── Template editor with preview ───
function TemplateEditor({
  template, onSave, saving
}: {
  template: { id: string; template_key: string; subject: string; body_html: string; description: string | null };
  onSave: (subject: string, body_html: string) => void;
  saving: boolean;
}) {
  const [subject, setSubject] = useState(template.subject);
  const [bodyHtml, setBodyHtml] = useState(template.body_html);
  const [showPreview, setShowPreview] = useState(false);
  const dirty = subject !== template.subject || bodyHtml !== template.body_html;

  const variableHints: Record<string, string[]> = {
    ranking_complete: ["user_name", "job_title", "resume_count", "job_id", "app_url"],
    resume_received: ["user_name", "job_title", "attachment_count", "filename", "job_id", "app_url"],
  };
  const vars = variableHints[template.template_key] || [];

  const prettyName = template.template_key.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <FileText className="h-4 w-4" /> {prettyName}
          </CardTitle>
          <Button variant="ghost" size="sm" className="gap-1.5 text-xs" onClick={() => setShowPreview(!showPreview)}>
            <Eye className="h-3 w-3" /> {showPreview ? "Edit" : "Preview"}
          </Button>
        </div>
        {template.description && <CardDescription>{template.description}</CardDescription>}
      </CardHeader>
      <CardContent className="space-y-4">
        {vars.length > 0 && (
          <div className="flex flex-wrap gap-1.5">
            <span className="text-xs text-muted-foreground">Variables:</span>
            {vars.map((v) => (
              <Badge key={v} variant="outline" className="text-[11px] font-mono px-1.5 py-0">{`{{${v}}}`}</Badge>
            ))}
          </div>
        )}

        {showPreview ? (
          <div className="rounded-lg border bg-white dark:bg-background p-4">
            <p className="text-xs text-muted-foreground mb-2">Subject: <strong>{subject}</strong></p>
            <div className="border rounded p-3 text-sm" dangerouslySetInnerHTML={{ __html: bodyHtml }} />
          </div>
        ) : (
          <>
            <div className="space-y-2">
              <Label className="text-sm font-medium">Subject Line</Label>
              <Input value={subject} onChange={(e) => setSubject(e.target.value)} />
            </div>
            <div className="space-y-2">
              <Label className="text-sm font-medium">Email Body (HTML)</Label>
              <Textarea value={bodyHtml} onChange={(e) => setBodyHtml(e.target.value)} className="font-mono text-xs min-h-[180px]" />
            </div>
          </>
        )}

        <Button onClick={() => onSave(subject, bodyHtml)} disabled={!dirty || saving} className="gap-2">
          <Save className="h-4 w-4" />
          {saving ? "Saving..." : "Save Template"}
        </Button>
      </CardContent>
    </Card>
  );
}

